begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('eeeeeeee-0000-4000-8000-000000000001','timer-a@example.test'),('eeeeeeee-0000-4000-8000-000000000002','timer-b@example.test');
create function pg_temp.timer(s uuid,w uuid,r bigint,a text,c uuid default gen_random_uuid()) returns jsonb language sql as $$
  select public.apply_work_session_command(c,s,w,r,'2000-01-01T00:00:00Z','timer-test',a)
$$;
select ok(not has_function_privilege('anon','public.apply_work_session_command(uuid,uuid,uuid,bigint,timestamptz,text,text)','execute'),'anonymous timer commands denied');
select ok(not has_function_privilege('anon','public.get_work_session(uuid)','execute'),'anonymous timer reads denied');
select ok(not has_table_privilege('authenticated','public.work_sessions','INSERT'),'session direct insert denied');
select ok(not has_table_privilege('authenticated','public.work_sessions','UPDATE'),'session direct update denied');
select ok(not has_table_privilege('authenticated','public.work_sessions','DELETE'),'session direct delete denied');
select ok(not has_table_privilege('authenticated','public.work_session_events','INSERT'),'event direct insert denied');
select ok(not has_table_privilege('authenticated','public.work_session_events','UPDATE'),'event direct update denied');
select ok(not has_table_privilege('authenticated','public.work_session_time_adjustments','INSERT'),'correction direct insert denied');
set local role authenticated;
set local request.jwt.claim.sub='eeeeeeee-0000-4000-8000-000000000001';
select set_config('test.tp',public.create_project(gen_random_uuid(),'타이머',null)->>'id',true);
select set_config('test.tw',public.get_project_detail(current_setting('test.tp')::uuid)->'parts'->0->>'workItemId',true);
select set_config('test.tpart',public.apply_project_part_command(current_setting('test.tp')::uuid,gen_random_uuid(),0,'{"type":"create","name":"소매"}')::text,true);
select set_config('test.ts','eeeeeeee-1000-4000-8000-000000000001',true);
select set_config('test.tc','eeeeeeee-2000-4000-8000-000000000001',true);
select is(public.get_work_session()->'state','null'::jsonb,'no active session is idle');
select is(public.apply_work_session_command(gen_random_uuid(),gen_random_uuid(),current_setting('test.tw')::uuid,0,'10000-01-01Z','timer-test','start')->>'reason','invalid_command','timestamps outside supported JavaScript calendar range rejected');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,0,'start',current_setting('test.tc')::uuid)->>'status','applied','start accepted');
select is(public.get_work_session()->'state'->>'status','running','active session restored from server');
select ok((public.get_work_session()->'state'->>'startedAt')::timestamptz>'2000-01-01Z'::timestamptz,'server clock, not requested timestamp, determines duration');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,0,'start',current_setting('test.tc')::uuid)->>'status','duplicate','start retransmission idempotent');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,0,'end',current_setting('test.tc')::uuid)->>'reason','command_id_reused','same command ID changed content denied');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,0,'pause')->>'status','conflict','stale revision conflict');
select is((select count(*) from public.work_session_events),1::bigint,'duplicates/rejected/conflict create no events');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,1,'resume')->>'reason','invalid_transition','running cannot resume again');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,1,'pause')->>'status','applied','pause accepted');
select is(public.get_work_session()->'state'->>'status','paused','paused session remains active');
select is(pg_temp.timer(gen_random_uuid(),(current_setting('test.tpart')::jsonb->>'workItemId')::uuid,0,'start')->>'reason','active_session_exists','paused session blocks starting on another part');
select is(public.get_work_session()->'state'->>'workItemId',current_setting('test.tw'),'looking at another part does not move the session');
select throws_ok(format('select public.update_project(%L,1,''타이머'',null,''paused'')',current_setting('test.tp')),'23514',null,'paused project transition requires ending paused session');
select throws_ok(format('select public.update_project(%L,1,''타이머'',null,''completed'')',current_setting('test.tp')),'23514',null,'completed project transition requires ending session');
select throws_ok(format('select public.delete_project(%L,1)',current_setting('test.tp')),'23514',null,'project deletion requires ending session');
reset role;
select throws_ok(format('insert into public.work_sessions(id,user_id,work_item_id,status,started_at,last_resumed_at,last_transition_at,revision,last_command_id,created_at,updated_at) values(gen_random_uuid(),%L,%L,''running'',date_trunc(''milliseconds'',now()),date_trunc(''milliseconds'',now()),date_trunc(''milliseconds'',now()),1,gen_random_uuid(),date_trunc(''milliseconds'',now()),date_trunc(''milliseconds'',now()))','eeeeeeee-0000-4000-8000-000000000001',current_setting('test.tw')),'23505',null,'unique active index also protects writes outside RPC');
set local role authenticated;
select set_config('test.tpaused',public.get_work_session()->'state'->>'accumulatedMs',true);
select pg_sleep(0.01);
select is(public.get_work_session()->'state'->>'accumulatedMs',current_setting('test.tpaused'),'paused duration does not advance');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,2,'resume')->>'status','applied','resume accepted');
select pg_sleep(0.01);
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,3,'end')->>'status','applied','end accepted');
select is(public.get_work_session()->'state','null'::jsonb,'end frees active slot');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,4,'resume')->>'reason','session_ended','ended session cannot resume');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,0,'start',current_setting('test.tc')::uuid)->'state'->>'revision','1','retry returns original result even after newer events');
select is(public.get_work_session(current_setting('test.ts')::uuid)->'state'->>'revision','4','duplicate does not overwrite latest snapshot');
select is((select accumulated_ms from public.work_sessions where id=current_setting('test.ts')::uuid),
  (select sum(floor(extract(epoch from (effective_at-(before_state->>'lastResumedAt')::timestamptz))*1000))::bigint from public.work_session_events where session_id=current_setting('test.ts')::uuid and event_type in ('pause','end')),
  'final duration equals sum of running segments, not total lifespan');
select is(jsonb_array_length(public.get_work_session(current_setting('test.ts')::uuid)->'events'),4,'all ordered session events restored');
select is((select revision from public.work_items where id=current_setting('test.tw')::uuid),0::bigint,'timer does not change counter revision');
select is((select revision from public.projects where id=current_setting('test.tp')::uuid),1::bigint,'timer does not change project metadata revision');
select set_config('test.tsnapshot',public.get_work_session(current_setting('test.ts')::uuid)->'state' #>> '{}',true);
select set_config('test.ts2','eeeeeeee-1000-4000-8000-000000000002',true);
select is(pg_temp.timer(current_setting('test.ts2')::uuid,(current_setting('test.tpart')::jsonb->>'workItemId')::uuid,0,'start')->>'status','applied','another part may start after previous session ends');
select throws_ok(format('select public.apply_project_part_command(%L,gen_random_uuid(),1,%L)',current_setting('test.tp'),jsonb_build_object('type','delete','partId',current_setting('test.tpart')::jsonb->>'partId')),'23514',null,'running session blocks part deletion');
select is(public.apply_project_part_command(current_setting('test.tp')::uuid,gen_random_uuid(),1,jsonb_build_object('type','rename','partId',current_setting('test.tpart')::jsonb->>'partId','name','이름 변경'))->>'status','applied','rename allowed without moving session');
select is(public.get_work_session()->'state'->>'workItemId',current_setting('test.tpart')::jsonb->>'workItemId','part rename preserves work item/session');
select is(pg_temp.timer(current_setting('test.ts2')::uuid,(current_setting('test.tpart')::jsonb->>'workItemId')::uuid,1,'pause')->>'status','applied','second session paused');
select throws_ok(format('select public.apply_project_part_command(%L,gen_random_uuid(),2,%L)',current_setting('test.tp'),jsonb_build_object('type','delete','partId',current_setting('test.tpart')::jsonb->>'partId')),'23514',null,'paused session also blocks part deletion');
select is(pg_temp.timer(current_setting('test.ts2')::uuid,(current_setting('test.tpart')::jsonb->>'workItemId')::uuid,2,'end')->>'status','applied','end while paused accepted');
select is(public.update_project(current_setting('test.tp')::uuid,2,'타이머',null,'paused')->>'result','updated','pause project after ending all sessions');
select is(pg_temp.timer(gen_random_uuid(),current_setting('test.tw')::uuid,0,'start')->>'reason','project_or_part_unavailable','paused project cannot start');
select is(public.update_project(current_setting('test.tp')::uuid,3,'타이머',null,'completed')->>'result','updated','complete project');
select is(pg_temp.timer(gen_random_uuid(),current_setting('test.tw')::uuid,0,'start')->>'reason','project_or_part_unavailable','completed project cannot start');
select is(public.update_project(current_setting('test.tp')::uuid,4,'타이머',null,'active')->>'result','updated','reactivate project');
select is(public.apply_project_part_command(current_setting('test.tp')::uuid,gen_random_uuid(),5,jsonb_build_object('type','delete','partId',current_setting('test.tpart')::jsonb->>'partId'))->>'status','applied','part deletion allowed after session end');
select is(pg_temp.timer(gen_random_uuid(),(current_setting('test.tpart')::jsonb->>'workItemId')::uuid,0,'start')->>'reason','project_or_part_unavailable','deleted part cannot start');
select is(public.delete_project(current_setting('test.tp')::uuid,6)->>'result','deleted','project deletion allowed after end');
select is(pg_temp.timer(gen_random_uuid(),current_setting('test.tw')::uuid,0,'start')->>'reason','project_or_part_unavailable','deleted project cannot start');
select is(public.get_work_session(current_setting('test.ts')::uuid)->'state',current_setting('test.tsnapshot')::jsonb,'own historical session stays readable after project deletion');
select is(public.restore_project(current_setting('test.tp')::uuid,gen_random_uuid(),7)->>'status','restored','project recovered');
select is(public.get_work_session(current_setting('test.ts')::uuid)->'state',current_setting('test.tsnapshot')::jsonb,'recovery does not resume or rewrite sessions');
select is(pg_temp.timer(gen_random_uuid(),(current_setting('test.tpart')::jsonb->>'workItemId')::uuid,0,'start')->>'reason','project_or_part_unavailable','individually deleted part stays unavailable after recovery');
select set_config('test.tstandalone',public.create_counter_work_item()->'state'->>'workItemId',true);
select set_config('test.ts3','eeeeeeee-1000-4000-8000-000000000003',true);
select is(pg_temp.timer(current_setting('test.ts3')::uuid,current_setting('test.tstandalone')::uuid,0,'start')->>'status','applied','standalone account counter supports session');
select throws_ok(format('select public.convert_counter_to_project(%L,gen_random_uuid(),0,''전환'')',current_setting('test.tstandalone')),'23514',null,'active standalone session cannot be silently attached during conversion');
select is(pg_temp.timer(current_setting('test.ts3')::uuid,current_setting('test.tstandalone')::uuid,1,'end')->>'status','applied','standalone session ended');
select is(public.convert_counter_to_project(current_setting('test.tstandalone')::uuid,gen_random_uuid(),0,'전환')->>'status','converted','conversion possible after ending session');
set local request.jwt.claim.sub='eeeeeeee-0000-4000-8000-000000000002';
select is((select count(*) from public.work_sessions),0::bigint,'RLS hides another owner sessions');
select is((select count(*) from public.work_session_events),0::bigint,'RLS hides another owner events');
select throws_ok(format('select public.get_work_session(%L)',current_setting('test.ts')),'P0002',null,'other owner read RPC denied');
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tw')::uuid,4,'end')->>'reason','work_item_unavailable','other owner command denied');
select set_config('test.tother',public.create_counter_work_item()->'state'->>'workItemId',true);
select is(pg_temp.timer(current_setting('test.ts')::uuid,current_setting('test.tother')::uuid,0,'start')->>'reason','session_identity_mismatch','another owner cannot reuse an existing session ID');
select set_config('test.tbs',gen_random_uuid()::text,true);
select is(pg_temp.timer(current_setting('test.tbs')::uuid,current_setting('test.tother')::uuid,0,'start',current_setting('test.tc')::uuid)->>'status','applied','command IDs scoped to user, same ID may be used by another owner');
select is(pg_temp.timer(current_setting('test.tbs')::uuid,current_setting('test.tother')::uuid,1,'end')->>'status','applied','other user independent session ended');
reset role;
select throws_ok(format('update public.work_sessions set accumulated_ms=-1 where id=%L',current_setting('test.ts')),'23514',null,'negative durations rejected by CHECK');
select throws_ok(format('update public.work_sessions set last_resumed_at=started_at where id=%L',current_setting('test.ts')),'23514',null,'ended session cannot have a running segment');
select throws_ok(format('update public.work_session_events set device_id=''tampered'' where session_id=%L',current_setting('test.ts')),'23514',null,'events append only');
select throws_ok(format('delete from public.work_session_events where session_id=%L',current_setting('test.ts')),'23514',null,'events cannot be deleted');
insert into public.work_session_time_adjustments(id,user_id,session_id,command_id,previous_adjusted_ms,adjusted_ms,reason)
  values('eeeeeeee-3000-4000-8000-000000000001','eeeeeeee-0000-4000-8000-000000000001',current_setting('test.ts')::uuid,gen_random_uuid(),0,100,'테스트 전용 향후 정정 이력 구조');
select throws_ok('update public.work_session_time_adjustments set adjusted_ms=200','23514',null,'future adjustments append only');
select throws_ok('delete from public.work_session_time_adjustments','23514',null,'future adjustment history cannot be deleted');
select is((select accumulated_ms::text from public.work_sessions where id=current_setting('test.ts')::uuid),current_setting('test.tsnapshot')::jsonb->>'accumulatedMs','adjustments do not overwrite original measured time');
select * from finish();
rollback;
